/* JellymountPlus bundle — generated by build.sh. Do not edit; edit styles/ and extras/scripts/ instead. */
/* ===== extras/scripts/jellymountplus.js ===== */
/* ============================================================
   JellymountPlus — Core bootstrap
   Namespace, config, Jellyfin API helpers and the page/view
   lifecycle that every module plugs into.
   ============================================================ */
(function () {
    'use strict';

    if (window.JellymountPlus && window.JellymountPlus.__loaded) return;

    var JMP = {
        __loaded: true,
        version: '1.0.0',
        modules: {},
        _pageCleanups: [],
        _currentView: null
    };

    /* ---------------- Config ---------------- */

    var DEFAULTS = {
        hero: true,
        heroAutoRotate: true,
        heroRotateMs: 18000,
        heroItemLimit: 8,
        hoverPreview: true,
        hoverPreviewDelayMs: 420,
        railButtons: true,
        logoText: 'JellymountPlus',
        logoUrl: null,            // e.g. 'jellymountplus/assets/logo/jellymountplus.svg'
        debug: false
    };

    function readConfig() {
        var cfg = {};
        try {
            if (window.JellymountPlusConfig) cfg = window.JellymountPlusConfig;
            var stored = localStorage.getItem('jmp-config');
            if (stored) {
                try { cfg = Object.assign(cfg, JSON.parse(stored)); } catch (e) { /* noop */ }
            }
        } catch (e) { /* noop */ }
        return Object.assign({}, DEFAULTS, cfg);
    }

    JMP.config = readConfig();

    JMP.log = function () {
        if (!JMP.config.debug) return;
        var args = Array.prototype.slice.call(arguments);
        args.unshift('[JellymountPlus]');
        console.debug.apply(console, args);
    };

    /* ---------------- API helpers ---------------- */

    function api() {
        if (window.ApiClient) return window.ApiClient;
        var sc = window.ServerConnections;
        if (sc && sc.currentApiClient) {
            try { return sc.currentApiClient(); } catch (e) { return null; }
        }
        return null;
    }
    JMP.api = api;

    JMP.userId = function () {
        var c = api();
        if (!c) return null;
        try { return c.getCurrentUserId(); } catch (e) { return null; }
    };

    JMP.serverId = function () {
        var c = api();
        if (!c) return null;
        try { return c.serverId(); } catch (e) { return null; }
    };

    /* Build a server image URL for an item. */
    JMP.imageUrl = function (item, opts) {
        opts = opts || {};
        var c = api();
        if (!c || !item) return '';
        var type = opts.type || 'Primary';
        var tag = opts.tag;

        if (!tag) {
            if (type === 'Primary') tag = item.ImageTags && item.ImageTags.Primary;
            else if (type === 'Backdrop') tag = item.BackdropImageTags && item.BackdropImageTags[opts.index || 0];
            else if (type === 'Logo') tag = item.ImageTags && item.ImageTags.Logo;
            else if (type === 'Thumb') tag = item.ImageTags && item.ImageTags.Thumb;
        }
        if (!tag) return '';

        var params = {
            tag: tag,
            maxWidth: opts.width || 800,
            quality: opts.quality || 90
        };
        if (opts.maxHeight) params.maxHeight = opts.maxHeight;

        var id = opts.itemId || item.Id;
        var base = 'Items/' + id + '/Images/' + type;
        if (type === 'Backdrop' && (opts.index != null)) base += '/' + opts.index;
        return c.getUrl(base, params);
    };

    /* Backdrop with graceful fallbacks (spec: artwork priority). */
    JMP.backdropUrl = function (item, width) {
        var u = JMP.imageUrl(item, { type: 'Backdrop', index: 0, width: width || 1920, quality: 88 });
        if (u) return u;
        u = JMP.imageUrl(item, { type: 'Thumb', width: width || 1920 });
        if (u) return u;
        u = JMP.imageUrl(item, { type: 'Primary', width: width || 1920 });
        return u || '';
    };

    JMP.logoUrl = function (item, width) {
        return JMP.imageUrl(item, { type: 'Logo', width: width || 800, quality: 90 });
    };

    JMP.posterUrl = function (item, width) {
        var u = JMP.imageUrl(item, { type: 'Primary', width: width || 500 });
        if (!u && item.SeriesId) {
            u = JMP.imageUrl({ Id: item.SeriesId, ImageTags: item.SeriesPrimaryImageTag ? { Primary: item.SeriesPrimaryImageTag } : {} }, { type: 'Primary', width: width || 500 });
        }
        return u || '';
    };

    JMP.thumbUrl = function (item, width) {
        var u = JMP.imageUrl(item, { type: 'Thumb', width: width || 800 });
        if (!u) u = JMP.imageUrl(item, { type: 'Backdrop', index: 0, width: width || 800 });
        if (!u) u = JMP.imageUrl(item, { type: 'Primary', width: width || 800 });
        return u || '';
    };

    /* ---------------- Requests ---------------- */

    JMP.getJSON = function (path, params) {
        var c = api();
        if (!c) return Promise.reject(new Error('no apiclient'));
        return c.getJSON(c.getUrl(path, params));
    };

    JMP.getItem = function (id) {
        var uid = JMP.userId();
        var c = api();
        if (!c || !uid || !id) return Promise.reject(new Error('missing id/user'));
        return c.getItem(uid, id).then ? c.getItem(uid, id) : c.getJSON(c.getUrl('Users/' + uid + '/Items/' + id, { Fields: ITEM_FIELDS }));
    };

    var ITEM_FIELDS = [
        'Overview', 'ProductionYear', 'RunTimeTicks', 'OfficialRating',
        'CommunityRating', 'Genres', 'MediaSourceCount', 'PrimaryImageAspectRatio',
        'SeriesName', 'ParentIndexNumber', 'IndexNumber', 'SeasonName',
        'PremiereDate', 'DateCreated', 'ProviderIds', 'Taglines', 'Studios',
        'ChildCount', 'RecursiveItemCount', 'BackdropImageTags'
    ].join(',');
    JMP.ITEM_FIELDS = ITEM_FIELDS;

    /* ---------------- Formatting ---------------- */

    JMP.esc = function (s) {
        if (s == null) return '';
        return String(s).replace(/[&<>"']/g, function (ch) {
            return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch];
        });
    };

    JMP.fmtRuntime = function (ticks) {
        if (!ticks || ticks <= 0) return '';
        var totalMin = Math.round(ticks / 600000000);
        var h = Math.floor(totalMin / 60);
        var m = totalMin % 60;
        if (h > 0) return h + 'h' + (m ? ' ' + m + 'm' : '');
        return m + 'm';
    };

    JMP.fmtSeasonEp = function (item) {
        if (item.Type !== 'Episode') return '';
        var s = item.ParentIndexNumber != null ? 'S' + item.ParentIndexNumber : '';
        var e = item.IndexNumber != null ? 'E' + item.IndexNumber : '';
        var se = (s && e) ? s + ' ' + e : (s || e);
        var name = item.Name && item.Name !== ('Episode ' + item.IndexNumber) ? ': ' + item.Name : '';
        return se + name;
    };

    /* Age badge from real metadata only (no fabrication). */
    JMP.badgeFor = function (item) {
        var now = Date.now();
        var created = item.DateCreated ? new Date(item.DateCreated).getTime() : 0;
        var premiered = item.PremiereDate ? new Date(item.PremiereDate).getTime() : 0;
        var DAY = 86400000;
        if (item.Type === 'Episode' && premiered && (now - premiered) < 14 * DAY) return 'NEW EPISODE';
        if (item.Type === 'Season' && premiered && (now - premiered) < 30 * DAY) return 'NEW SEASON';
        if (created && (now - created) < 14 * DAY) return 'JUST ADDED';
        if (premiered && (now - premiered) < 30 * DAY) return 'NEW';
        return '';
    };

    /* Meta chips for hero / preview: year · rating · runtime · score */
    JMP.metaChips = function (item) {
        var chips = [];
        var badge = JMP.badgeFor(item);
        if (badge) chips.push('<span class="jmp-badge">' + JMP.esc(badge) + '</span>');
        if (item.ProductionYear) chips.push('<span>' + item.ProductionYear + '</span>');
        if (item.OfficialRating) chips.push('<span class="jmp-meta-badge-age">' + JMP.esc(item.OfficialRating) + '</span>');
        if (item.Type === 'Series' && item.ChildCount) {
            chips.push('<span>' + item.ChildCount + (item.ChildCount === 1 ? ' Season' : ' Seasons') + '</span>');
        } else if (item.Type === 'Episode') {
            var se = JMP.fmtSeasonEp(item).split(':')[0];
            if (se) chips.push('<span>' + JMP.esc(se) + '</span>');
        } else {
            var rt = JMP.fmtRuntime(item.RunTimeTicks);
            if (rt) chips.push('<span>' + rt + '</span>');
        }
        if (item.CommunityRating) {
            chips.push('<span class="jmp-meta-rating">' + (Math.round(item.CommunityRating * 10) / 10) + '</span>');
        }
        return chips.join('');
    };

    /* Card attribute payload reused by injected itemAction elements so
       Jellyfin's own shortcuts/playback machinery handles the clicks.
       (Mirrors getItemInfoFromCard in jellyfin-web components/shortcuts.) */
    JMP.itemDataAttrs = function (item, action) {
        var ticks = (item.UserData && item.UserData.PlaybackPositionTicks) || 0;
        var attrs =
            ' data-id="' + JMP.esc(item.Id) + '"' +
            ' data-serverid="' + JMP.esc(item.ServerId || JMP.serverId() || '') + '"' +
            ' data-type="' + JMP.esc(item.Type || '') + '"' +
            ' data-mediatype="' + JMP.esc(item.MediaType || '') + '"' +
            ' data-isfolder="' + (item.IsFolder ? 'true' : 'false') + '"' +
            ' data-positionticks="' + ticks + '"' +
            ' data-action="' + JMP.esc(action || 'link') + '"';
        if (item.ChannelId) attrs += ' data-channelid="' + JMP.esc(item.ChannelId) + '"';
        if (item.SeriesId) attrs += ' data-seriesid="' + JMP.esc(item.SeriesId) + '"';
        if (item.CollectionType) attrs += ' data-collectiontype="' + JMP.esc(item.CollectionType) + '"';
        return attrs;
    };

    /* Same payload as setAttribute calls on a live element. */
    JMP.applyItemAttrs = function (el, item, action) {
        var ticks = (item.UserData && item.UserData.PlaybackPositionTicks) || 0;
        el.setAttribute('data-id', item.Id);
        el.setAttribute('data-serverid', item.ServerId || JMP.serverId() || '');
        el.setAttribute('data-type', item.Type || '');
        el.setAttribute('data-mediatype', item.MediaType || '');
        el.setAttribute('data-isfolder', item.IsFolder ? 'true' : 'false');
        el.setAttribute('data-positionticks', ticks);
        el.setAttribute('data-action', action || 'link');
        if (item.ChannelId) el.setAttribute('data-channelid', item.ChannelId);
        if (item.SeriesId) el.setAttribute('data-seriesid', item.SeriesId);
        if (item.CollectionType) el.setAttribute('data-collectiontype', item.CollectionType);
    };

    JMP.isResumeable = function (item) {
        var ud = item.UserData;
        return !!(ud && ud.PlaybackPositionTicks > 0);
    };

    JMP.progressPct = function (item) {
        var ud = item.UserData;
        if (!ud || !ud.PlaybackPositionTicks || !item.RunTimeTicks) return 0;
        return Math.min(100, Math.round((ud.PlaybackPositionTicks / item.RunTimeTicks) * 1000) / 10);
    };

    /* ---------------- DOM helpers ---------------- */

    /* Create a real emby-itemscontainer element so descendants with
       class="itemAction" + data-action get native Jellyfin behaviour
       (play / resume / menu / link) inside our injected UI. */
    JMP.itemsContainer = function (className) {
        var el = document.createElement('div', 'emby-itemscontainer');
        el.className = 'itemsContainer ' + (className || '');
        el.setAttribute('data-contextmenu', 'false');
        return el;
    };

    JMP.el = function (tag, className, html) {
        var el = document.createElement(tag);
        if (className) el.className = className;
        if (html != null) el.innerHTML = html;
        return el;
    };

    JMP.reducedMotion = function () {
        return window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    };

    JMP.finePointer = function () {
        return window.matchMedia && window.matchMedia('(hover: hover) and (pointer: fine)').matches;
    };

    /* ---------------- Page / view lifecycle ---------------- */

    function cleanupPage() {
        var fns = JMP._pageCleanups.slice();
        JMP._pageCleanups = [];
        fns.forEach(function (fn) { try { fn(); } catch (e) { console.error('[JellymountPlus] cleanup error', e); } });
        JMP._currentView = null;
    }

    /* Register a page-scoped teardown. */
    JMP.onCleanup = function (fn) {
        JMP._pageCleanups.push(fn);
    };

    /* viewshow bubbles from every React <Page> and legacy view. */
    document.addEventListener('viewshow', function (e) {
        cleanupPage();
        JMP._currentView = e.target;
        var view = e.target;
        Object.keys(JMP.modules).forEach(function (name) {
            var mod = JMP.modules[name];
            if (mod && typeof mod.onView === 'function') {
                try { mod.onView(view, e.detail || {}); } catch (err) { console.error('[JellymountPlus] module "' + name + '" error', err); }
            }
        });
    }, true);

    document.addEventListener('viewhide', cleanupPage, true);
    window.addEventListener('pagehide', cleanupPage);

    /* ---------------- Module registry ---------------- */

    JMP.register = function (name, mod) {
        JMP.modules[name] = mod;
        /* If a view is already active (late script load), prime it now. */
        if (JMP._currentView && mod && typeof mod.onView === 'function') {
            try { mod.onView(JMP._currentView, {}); } catch (e) { console.error('[JellymountPlus]', e); }
        }
    };

    /* Wait until the ApiClient is usable, then run once. */
    JMP.whenReady = function (fn) {
        if (api() && JMP.userId()) { fn(); return; }
        var tries = 0;
        var t = setInterval(function () {
            tries++;
            if (api() && JMP.userId()) {
                clearInterval(t);
                fn();
            } else if (tries > 200) {
                clearInterval(t);
            }
        }, 150);
    };

    /* Scoped, throttled DOM watcher. Returns a disconnect function that is
       also auto-registered for page cleanup. */
    JMP.watch = function (root, predicate, cb, opts) {
        opts = opts || {};
        var fired = false;
        var pending = false;
        var observer = new MutationObserver(function () {
            if (pending) return;
            pending = true;
            setTimeout(function () {
                pending = false;
                if (fired && opts.once !== false) return;
                try {
                    var hit = predicate();
                    if (hit) {
                        if (opts.once !== false) { fired = true; observer.disconnect(); }
                        cb(hit);
                    }
                } catch (e) { console.error('[JellymountPlus] watcher error', e); }
            }, opts.debounceMs || 60);
        });
        observer.observe(root || document.body, { childList: true, subtree: true });
        var disconnect = function () { observer.disconnect(); };
        JMP.onCleanup(disconnect);
        return disconnect;
    };

    /* Prime a module immediately if the matching view is on screen —
       needed when scripts load after navigation already happened. */
    JMP.prime = function () {
        var view = document.querySelector('[data-role="page"]') || document.querySelector('.page');
        if (view && JMP._currentView !== view) {
            JMP._currentView = view;
            Object.keys(JMP.modules).forEach(function (name) {
                var mod = JMP.modules[name];
                if (mod && typeof mod.onView === 'function') {
                    try { mod.onView(view, {}); } catch (e) { console.error('[JellymountPlus]', e); }
                }
            });
        }
    };

    window.JellymountPlus = JMP;
    JMP.log('core loaded');
})();
/* ===== extras/scripts/navigation.js ===== */
/* ============================================================
   JellymountPlus — Top Navigation behaviour
   Injects the JellymountPlus logo, relabels Favorites as
   "My List", adds username+caret next to the avatar, and drives
   the transparent → solid nav transition on scroll.
   ============================================================ */
(function () {
    'use strict';

    var JMP = window.JellymountPlus;
    if (!JMP) return;

    var logoObserver = null;
    var scrollBound = false;

    /* ---------------- Logo ---------------- */

    function logoMarkup() {
        if (JMP.config.logoUrl) {
            return '<img src="' + JMP.esc(JMP.config.logoUrl) + '" alt="JellymountPlus">';
        }
        var text = JMP.config.logoText || 'JellymountPlus';
        /* Split trailing "Plus" so it renders in brand blue. */
        var idx = text.lastIndexOf('Plus');
        if (idx > 0) {
            return '<span class="jmp-logo-text">' + JMP.esc(text.slice(0, idx)) + '</span>' +
                   '<span class="jmp-logo-text jmp-logo-plus">' + JMP.esc(text.slice(idx)) + '</span>';
        }
        return '<span class="jmp-logo-text">' + JMP.esc(text) + '</span>';
    }

    function buildLogo() {
        var a = document.createElement('a');
        a.className = 'jmp-logo';
        a.href = '#/';
        a.setAttribute('aria-label', 'JellymountPlus home');
        a.innerHTML = logoMarkup();
        return a;
    }

    /* ---------------- Toolbar wiring ---------------- */

    function wireModernToolbar(toolbar) {
        if (toolbar.dataset.jmpNav) return;
        toolbar.dataset.jmpNav = '1';

        /* Logo before the first button group */
        var firstGroup = toolbar.querySelector('.MuiStack-root') || toolbar.firstElementChild;
        if (firstGroup && !toolbar.querySelector('.jmp-logo')) {
            toolbar.insertBefore(buildLogo(), firstGroup);
        }
        document.documentElement.classList.add('jmp-logo-active');

        /* Relabel the "Favorites" nav entry as "My List". */
        var favBtn = toolbar.querySelector('a[href*="tab=1"], .MuiButton-root[href*="tab=1"]');
        if (favBtn && !favBtn.dataset.jmpMylist) {
            favBtn.dataset.jmpMylist = '1';
            /* Replace the trailing text node, keep the heart icon. */
            var nodes = Array.prototype.slice.call(favBtn.childNodes);
            var label = nodes.filter(function (n) { return n.nodeType === 3 && n.textContent.trim(); })[0];
            if (label) label.textContent = 'My List';
            else if (favBtn.lastChild && favBtn.lastChild.nodeType === 3) favBtn.lastChild.textContent = 'My List';
        }

        /* Username + caret next to the avatar IconButton. */
        var buttons = toolbar.querySelectorAll('.MuiIconButton-root');
        var avatarBtn = buttons.length ? buttons[buttons.length - 1] : null;
        if (avatarBtn && !avatarBtn.parentNode.querySelector('.jmp-user')) {
            JMP.whenReady(function () {
                var c = JMP.api();
                if (!c) return;
                Promise.resolve(c.getCurrentUser ? c.getCurrentUser() : null).then(function (user) {
                    if (!user || !user.Name || !avatarBtn.isConnected) return;
                    var wrap = JMP.el('span', 'jmp-user');
                    wrap.innerHTML = '<span class="jmp-user-name">' + JMP.esc(user.Name) + '</span>' +
                                     '<span class="material-icons jmp-user-caret" aria-hidden="true">expand_more</span>';
                    avatarBtn.parentNode.insertBefore(wrap, avatarBtn);
                    /* Clicking the label opens the same menu as the avatar. */
                    wrap.style.cursor = 'pointer';
                    wrap.addEventListener('click', function () { avatarBtn.click(); });
                }).catch(function () { /* noop */ });
            });
        }
    }

    function wireLegacyHeader(header) {
        if (header.dataset.jmpNav) return;
        header.dataset.jmpNav = '1';
        var left = header.querySelector('.headerLeft');
        if (left && !left.querySelector('.jmp-logo')) {
            left.appendChild(buildLogo());
        }
        document.documentElement.classList.add('jmp-logo-active');
    }

    function scan() {
        var toolbar = document.querySelector('header.MuiAppBar-root .MuiToolbar-root');
        if (toolbar) wireModernToolbar(toolbar);
        var skin = document.querySelector('.skinHeader');
        if (skin) wireLegacyHeader(skin);
    }

    function startObserver() {
        if (logoObserver) return;
        scan();
        logoObserver = new MutationObserver(function () {
            scan();
        });
        logoObserver.observe(document.body, { childList: true, subtree: true });
        /* The observer is cheap but permanent — nav persists across views. */
    }

    /* ---------------- Scroll → solid nav ---------------- */

    /* Jellyfin scrolls an inner container (window.scrollY stays 0), while
       emby-scroller fires horizontal events — track the vertically
       scrollable element we actually see events from. */
    var scroller = null;

    function onScroll(e) {
        var doc = document.documentElement;
        var y = window.scrollY || doc.scrollTop || 0;
        var t = e && e.target;
        if (t && t !== document && t !== window && typeof t.scrollTop === 'number' &&
                t.scrollHeight - t.clientHeight > 8) {
            scroller = t;
        }
        if (scroller && !scroller.isConnected) scroller = null;
        if (scroller) y = Math.max(y, scroller.scrollTop);
        if (JMP.config.debug) {
            console.log('[JellymountPlus] nav scroll y=' + y +
                ' target=' + (e && e.target && (e.target.id || e.target.className || e.target.nodeName)));
        }
        if (y > 36) doc.classList.add('jmp-nav-solid');
        else doc.classList.remove('jmp-nav-solid');
    }

    function bindScroll() {
        if (scrollBound) return;
        scrollBound = true;
        window.addEventListener('scroll', onScroll, { capture: true, passive: true });
        onScroll();
    }

    /* ---------------- Module ---------------- */

    JMP.register('navigation', {
        onView: function () {
            startObserver();
            bindScroll();
        }
    });

    /* Nav exists before the first viewshow in some shells. */
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function () { startObserver(); bindScroll(); });
    } else {
        startObserver();
        bindScroll();
    }
})();
/* ===== extras/scripts/hero.js ===== */
/* ============================================================
   JellymountPlus — Home Hero
   Injects the cinematic featured hero into the home tab:
   backdrop crossfade, logo/meta/overview, Play/Resume + My List,
   featured poster selector and optional slow auto-rotation.
   All data comes from the user's Jellyfin server via ApiClient.
   ============================================================ */
(function () {
    'use strict';

    var JMP = window.JellymountPlus;
    if (!JMP) return;

    var FADE_MS = 430;
    var BACKDROP_FADE_MS = 900;

    function mount(tabEl) {
        if (tabEl.querySelector('.jmp-hero')) return;

        var hero = JMP.el('div', 'jmp-hero jmp-skeleton');
        hero.setAttribute('data-hero', '');
        hero.innerHTML =
            '<div class="jmp-hero-backdrops">' +
                '<div class="jmp-hero-backdrop" data-layer="0"></div>' +
                '<div class="jmp-hero-backdrop" data-layer="1"></div>' +
            '</div>' +
            '<div class="jmp-hero-gradient jmp-hero-gradient-left"></div>' +
            '<div class="jmp-hero-gradient jmp-hero-gradient-bottom"></div>' +
            '<div class="jmp-hero-gradient jmp-hero-gradient-top"></div>' +
            '<div class="jmp-hero-content">' +
                '<img class="jmp-hero-logo" alt="" hidden>' +
                '<h1 class="jmp-hero-title" hidden></h1>' +
                '<div class="jmp-hero-meta"></div>' +
                '<p class="jmp-hero-overview"></p>' +
            '</div>' +
            '<div class="jmp-hero-selector" data-count="0"></div>';

        var sections = tabEl.querySelector('.sections');
        if (sections) tabEl.insertBefore(hero, sections);
        else tabEl.insertBefore(hero, tabEl.firstChild);

        /* Lets CSS drop the appbar spacer so the hero slides under the
           translucent nav (edge-to-edge look). */
        document.documentElement.classList.add('jmp-hero-active');

        /* Action row uses a real emby-itemscontainer so data-action="play|resume|link"
           buttons get native Jellyfin playback/navigation handling. */
        var actions = JMP.itemsContainer('jmp-hero-actions');
        hero.querySelector('.jmp-hero-content').appendChild(actions);

        var state = {
            items: [],
            index: -1,
            timer: null,
            pausedHover: false,
            pausedIdle: false,
            pausedOffscreen: false,
            activeLayer: 0,
            destroyed: false,
            favBusy: false
        };

        JMP.whenReady(function () {
            if (state.destroyed) return;
            loadFeatured(state, hero);
        });

        wireInteraction(state, hero);
        JMP.onCleanup(function () { destroy(state, hero); });
    }

    /* ---------------- Data ---------------- */

    function loadFeatured(state, hero) {
        var uid = JMP.userId();
        var c = JMP.api();
        if (!uid || !c) return;

        JMP.getJSON('Users/' + uid + '/Items', {
            IncludeItemTypes: 'Movie,Series',
            Recursive: true,
            SortBy: 'DateCreated',
            SortOrder: 'Descending',
            Limit: Math.max(12, (JMP.config.heroItemLimit || 8) * 3),
            ImageTypeLimit: 1,
            EnableImageTypes: 'Primary,Backdrop,Logo,Thumb',
            Fields: JMP.ITEM_FIELDS,
            EnableTotalRecordCount: false,
            ExcludeLocationTypes: 'Virtual'
        }).then(function (result) {
            if (state.destroyed) return;
            var items = (result && result.Items || [])
                .filter(function (i) {
                    return i.BackdropImageTags && i.BackdropImageTags.length && JMP.backdropUrl(i);
                })
                .slice(0, JMP.config.heroItemLimit || 8);

            if (!items.length) {
                hero.remove();
                return;
            }
            state.items = items;
            buildSelector(state, hero);
            select(state, hero, 0, true);
            hero.classList.remove('jmp-skeleton');
            maybeAutoRotate(state, hero);
        }).catch(function (err) {
            JMP.log('hero load failed', err);
            if (!state.destroyed) hero.remove();
        });
    }

    /* For series, the hero play button targets a resumable / next-up episode
       so "Resume" and "Play" always do something truthful. */
    function resolvePlayable(item) {
        if (item.Type !== 'Series') return Promise.resolve(item);
        var uid = JMP.userId();
        return JMP.getJSON('Users/' + uid + '/Items', {
            ParentId: item.Id,
            Recursive: true,
            Filters: 'IsResumable',
            Limit: 1,
            Fields: JMP.ITEM_FIELDS,
            EnableTotalRecordCount: false
        }).then(function (r) {
            var ep = r && r.Items && r.Items[0];
            if (ep) return ep;
            return JMP.getJSON('Shows/NextUp', {
                UserId: uid,
                SeriesId: item.Id,
                Limit: 1,
                Fields: JMP.ITEM_FIELDS
            }).then(function (n) {
                return (n && n.Items && n.Items[0]) || item;
            });
        }).catch(function () { return item; });
    }

    /* ---------------- Rendering ---------------- */

    function buildSelector(state, hero) {
        var track = hero.querySelector('.jmp-hero-selector');
        track.innerHTML = '';
        track.setAttribute('data-count', state.items.length);
        if (state.items.length < 2) return;

        state.items.forEach(function (item, i) {
            var btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'jmp-hero-card';
            btn.setAttribute('aria-label', item.Name || '');
            btn.setAttribute('data-index', i);
            var url = JMP.posterUrl(item, 342);
            if (url) {
                var img = document.createElement('img');
                img.src = url;
                img.alt = '';
                img.loading = 'lazy';
                btn.appendChild(img);
            }
            btn.addEventListener('click', function (e) {
                e.stopPropagation();
                select(state, hero, i, false);
                pauseAuto(state, hero, true);
            });
            btn.addEventListener('keydown', function (e) {
                if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
                    e.preventDefault();
                    e.stopPropagation();
                    var next = i + (e.key === 'ArrowRight' ? 1 : -1);
                    next = (next + state.items.length) % state.items.length;
                    select(state, hero, next, false);
                    var cards = track.querySelectorAll('.jmp-hero-card');
                    if (cards[next]) cards[next].focus();
                    pauseAuto(state, hero, true);
                }
            });
            track.appendChild(btn);
        });
    }

    function renderActions(state, hero, item, playable) {
        var actions = hero.querySelector('.jmp-hero-actions');
        actions.innerHTML = '';

        var resumable = playable && JMP.isResumeable(playable);
        var target = playable || item;
        var play = document.createElement('button');
        play.type = 'button';
        play.className = 'jmp-btn jmp-btn-play itemAction';
        play.innerHTML = '<span class="material-icons jmp-btn-icon" aria-hidden="true">play_arrow</span><span>' +
            JMP.esc(resumable ? 'Resume' : 'Play') + '</span>';
        JMP.applyItemAttrs(play, target, resumable ? 'resume' : 'play');
        actions.appendChild(play);

        /* My List — toggles Jellyfin Favorites. */
        var fav = item.UserData && item.UserData.IsFavorite;
        var mylist = document.createElement('button');
        mylist.type = 'button';
        mylist.className = 'jmp-btn jmp-btn-icon-round jmp-mylist' + (fav ? ' is-saved' : '');
        mylist.setAttribute('aria-label', 'My List');
        mylist.setAttribute('aria-pressed', fav ? 'true' : 'false');
        mylist.title = 'My List';
        mylist.innerHTML = '<span class="material-icons" aria-hidden="true">' +
            (fav ? 'check' : 'add') + '</span>';
        mylist.addEventListener('click', function (e) {
            e.stopPropagation();
            e.preventDefault();
            toggleFavorite(state, hero, item, mylist);
        });
        actions.appendChild(mylist);

        var more = document.createElement('a');
        more.className = 'jmp-btn jmp-btn-ghost itemAction';
        more.setAttribute('href', '#/details?id=' + encodeURIComponent(item.Id) +
            (item.ServerId ? '&serverId=' + encodeURIComponent(item.ServerId) : ''));
        more.innerHTML = '<span class="material-icons jmp-btn-icon" aria-hidden="true">info_outline</span><span>More Info</span>';
        actions.appendChild(more);
    }

    function toggleFavorite(state, hero, item, btn) {
        var c = JMP.api();
        if (!c || state.favBusy) return;
        state.favBusy = true;
        var makeFav = !(item.UserData && item.UserData.IsFavorite);
        c.updateFavoriteStatus(item.Id, makeFav).then(function () {
            item.UserData = item.UserData || {};
            item.UserData.IsFavorite = makeFav;
            btn.classList.toggle('is-saved', makeFav);
            btn.setAttribute('aria-pressed', makeFav ? 'true' : 'false');
            btn.querySelector('.material-icons').textContent = makeFav ? 'check' : 'add';
            state.favBusy = false;
        }).catch(function () { state.favBusy = false; });
    }

    function select(state, hero, index, instant) {
        if (state.destroyed || index === state.index || !state.items[index]) return;
        state.index = index;
        var item = state.items[index];

        /* selector highlight */
        var cards = hero.querySelectorAll('.jmp-hero-card');
        Array.prototype.forEach.call(cards, function (c) {
            c.classList.toggle('is-selected', parseInt(c.getAttribute('data-index'), 10) === index);
        });

        /* Keep the selected card inside the scrollable selector's viewport. */
        var track = hero.querySelector('.jmp-hero-selector');
        var selCard = cards[index];
        if (track && selCard && track.scrollWidth > track.clientWidth) {
            var cl = selCard.offsetLeft, cw = selCard.offsetWidth, vw = track.clientWidth;
            if (cl < track.scrollLeft || cl + cw > track.scrollLeft + vw) {
                track.scrollTo({
                    left: cl + cw - vw + 8,
                    behavior: (instant || JMP.reducedMotion()) ? 'auto' : 'smooth'
                });
            }
        }

        /* content fade out → swap → fade in */
        var doSwap = function () {
            var logo = hero.querySelector('.jmp-hero-logo');
            var title = hero.querySelector('.jmp-hero-title');
            var logoSrc = JMP.logoUrl(item, 800);

            if (logoSrc) {
                logo.src = logoSrc;
                logo.alt = item.Name || '';
                logo.hidden = false;
                title.hidden = true;
                title.textContent = '';
            } else {
                logo.hidden = true;
                logo.removeAttribute('src');
                title.hidden = false;
                title.textContent = item.Name || '';
            }

            hero.querySelector('.jmp-hero-meta').innerHTML = JMP.metaChips(item);
            hero.querySelector('.jmp-hero-overview').textContent = item.Overview || '';
            hero.querySelector('.jmp-hero-overview').hidden = !item.Overview;

            resolvePlayable(item).then(function (playable) {
                if (state.destroyed || state.items[state.index] !== item) return;
                renderActions(state, hero, item, playable);
            });

            hero.classList.remove('is-fading');
        };

        /* backdrop crossfade — preload before showing */
        var url = JMP.backdropUrl(item, 1920);
        var layers = hero.querySelectorAll('.jmp-hero-backdrop');
        var next = 1 - state.activeLayer;
        var applyBackdrop = function () {
            if (state.destroyed || state.items[state.index] !== item) return;
            layers[next].style.backgroundImage = url ? 'url("' + url + '")' : 'none';
            layers[next].classList.add('is-active');
            layers[state.activeLayer].classList.remove('is-active');
            state.activeLayer = next;
        };

        if (instant || JMP.reducedMotion()) {
            if (url) {
                var pre = new Image();
                pre.onload = function () { applyBackdrop(); doSwap(); };
                pre.onerror = function () { applyBackdrop(); doSwap(); };
                pre.src = url;
            } else { applyBackdrop(); doSwap(); }
            return;
        }

        hero.classList.add('is-fading');
        var proceed = function () { applyBackdrop(); doSwap(); };
        if (url) {
            var img = new Image();
            var done = false;
            img.onload = function () { if (!done) { done = true; proceed(); } };
            img.onerror = function () { if (!done) { done = true; proceed(); } };
            img.src = url;
            setTimeout(function () { if (!done) { done = true; proceed(); } }, 1500);
        } else {
            setTimeout(proceed, FADE_MS);
        }
    }

    /* ---------------- Auto rotation ---------------- */

    function isPaused(state) {
        return state.pausedHover || state.pausedIdle || state.pausedOffscreen || document.hidden;
    }

    function maybeAutoRotate(state, hero) {
        if (!JMP.config.heroAutoRotate || JMP.reducedMotion() || state.items.length < 2) return;
        var ms = JMP.config.heroRotateMs || 18000;
        state.timer = setInterval(function () {
            if (isPaused(state)) return;
            select(state, hero, (state.index + 1) % state.items.length, false);
        }, ms);
    }

    function pauseAuto(state, hero, untilIdle) {
        state.pausedIdle = true;
        if (untilIdle) {
            clearTimeout(state._resumeT);
            state._resumeT = setTimeout(function () { state.pausedIdle = false; }, (JMP.config.heroRotateMs || 18000) * 0.75);
        }
    }

    function wireInteraction(state, hero) {
        hero.addEventListener('pointerenter', function () { state.pausedHover = true; });
        hero.addEventListener('pointerleave', function () { state.pausedHover = false; });
        hero.addEventListener('focusin', function () { state.pausedHover = true; });
        hero.addEventListener('focusout', function () { state.pausedHover = false; });
        /* Pause rotation while the hero is scrolled off screen. */
        if ('IntersectionObserver' in window) {
            state._io = new IntersectionObserver(function (entries) {
                state.pausedOffscreen = !entries[0].isIntersecting;
            }, { threshold: 0.15 });
            state._io.observe(hero);
        }
    }

    function destroy(state, hero) {
        state.destroyed = true;
        clearInterval(state.timer);
        clearTimeout(state._resumeT);
        if (state._io) state._io.disconnect();
        document.documentElement.classList.remove('jmp-hero-active');
        if (hero.parentNode) hero.parentNode.removeChild(hero);
    }

    /* ---------------- Registration ---------------- */

    JMP.register('hero', {
        onView: function (view) {
            if (!JMP.config.hero) return;
            if (!view || !(view.id === 'indexPage' || view.classList.contains('homePage'))) return;

            var tab = view.querySelector('#homeTab') ||
                        view.querySelector('.tabContent[data-index="0"]');
            if (tab) {
                mount(tab);
            } else {
                JMP.watch(view, function () {
                    return view.querySelector('#homeTab') || view.querySelector('.tabContent[data-index="0"]');
                }, function (hit) { mount(hit); });
            }
        }
    });

    JMP.prime();
})();
/* ===== extras/scripts/rails.js ===== */
/* ============================================================
   JellymountPlus — Content Rails behaviour
   Edge-peek detection, keyboard arrow navigation between cards
   and real-metadata badges (one batched request per row).
   ============================================================ */
(function () {
    'use strict';

    var JMP = window.JellymountPlus;
    if (!JMP) return;

    var processedContainers = (typeof WeakSet !== 'undefined') ? new WeakSet() : { add: function(){}, has: function(){return false;} };
    var pendingFetch = null;
    var pendingIds = new Set();
    var idBadgeMap = {};

    /* ---------------- Edge peek / has-more ---------------- */

    function refreshSectionFlags() {
        var sections = document.querySelectorAll('.verticalSection');
        Array.prototype.forEach.call(sections, function (section) {
            var scroller = section.querySelector('[is="emby-scroller"]') || section.querySelector('.emby-scroller');
            if (!scroller) return;
            var slider = scroller.querySelector('.scrollSlider') || scroller;
            var overflow = slider.scrollWidth > scroller.clientWidth + 8;
            section.classList.toggle('jmp-has-more', overflow);
        });
    }

    var resizeT = null;
    window.addEventListener('resize', function () {
        clearTimeout(resizeT);
        resizeT = setTimeout(refreshSectionFlags, 200);
    }, { passive: true });

    /* ---------------- Keyboard navigation between cards ---------------- */

    document.addEventListener('keydown', function (e) {
        if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
        var card = e.target.closest && e.target.closest('.itemsContainer .card');
        if (!card) return;
        if (e.target.closest('.jmp-preview')) return;

        var dir = e.key === 'ArrowRight' ? 1 : -1;
        var rail = card.parentNode;
        var cards = rail.querySelectorAll(':scope > .card, :scope > .cardBox');
        var idx = Array.prototype.indexOf.call(cards, card);
        var next = cards[idx + dir];
        if (!next) return;

        e.preventDefault();
        e.stopPropagation();
        var target = next.matches('.card') ? (next.querySelector('.cardImageContainer, a, button') || next) : next;
        if (target.focus) target.focus();
        next.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: JMP.reducedMotion() ? 'auto' : 'smooth' });
    }, true);

    /* ---------------- Real-metadata badges ---------------- */

    function queueBadgeFetch(ids) {
        ids.forEach(function (id) { pendingIds.add(id); });
        clearTimeout(pendingFetch);
        pendingFetch = setTimeout(flushBadgeFetch, 120);
    }

    function flushBadgeFetch() {
        var uid = JMP.userId();
        if (!uid || !pendingIds.size) return;
        var all = Array.from(pendingIds);
        var ids = all.slice(0, 40);
        pendingIds = new Set(all.slice(40));
        JMP.log('badge fetch for', ids.length, 'items');
        JMP.getJSON('Users/' + uid + '/Items', {
            Ids: ids.join(','),
            Fields: 'DateCreated,PremiereDate,Type',
            EnableTotalRecordCount: false
        }).then(function (r) {
            (r && r.Items || []).forEach(function (item) {
                var b = JMP.badgeFor(item);
                if (b) idBadgeMap[item.Id] = b;
            });
            applyBadges();
            if (pendingIds.size) flushBadgeFetch();
        }).catch(function (e) { JMP.log('badge fetch failed', e); });
    }

    function applyBadges() {
        Object.keys(idBadgeMap).forEach(function (id) {
            var badge = idBadgeMap[id];
            if (!badge) return;
            var cards = document.querySelectorAll('.card[data-id="' + id + '"]');
            Array.prototype.forEach.call(cards, function (card) {
                if (card.querySelector('.jmp-card-badge')) return;
                var scalable = card.querySelector('.cardScalable') || card;
                var tag = JMP.el('span', 'jmp-card-badge jmp-badge', JMP.esc(badge));
                scalable.appendChild(tag);
            });
        });
    }

    function processContainer(container) {
        if (processedContainers.has(container)) return;
        processedContainers.add(container);

        var cards = container.querySelectorAll('.card[data-id]');
        var ids = [];
        for (var i = 0; i < cards.length && i < 12; i++) {
            ids.push(cards[i].getAttribute('data-id'));
        }
        JMP.log('rail container: ' + cards.length + ' cards');
        if (ids.length) queueBadgeFetch(ids);
    }

    function scan(root) {
        var containers = (root || document).querySelectorAll(
            '.verticalSection .itemsContainer, .sections .itemsContainer, .itemsContainer[data-parentid]'
        );
        Array.prototype.forEach.call(containers, processContainer);
        refreshSectionFlags();
    }

    /* ---------------- Module ---------------- */

    JMP.register('rails', {
        onView: function (view) {
            /* Sections render async — watch for containers appearing. */
            JMP.watch(view, function () {
                var c = view.querySelectorAll('.verticalSection .itemsContainer, .sections .itemsContainer');
                return c.length ? c : null;
            }, function () {
                scan(view);
            }, { once: false, debounceMs: 250 });

            scan(view);
        }
    });

    JMP.prime();
})();
/* ===== extras/scripts/hover-preview.js ===== */
/* ============================================================
   JellymountPlus — Expanded Hover Preview
   Netflix/P+-style delayed card expansion. One preview at a
   time, collision-aware positioning, proper teardown on
   scroll / escape / navigation.
   ============================================================ */
(function () {
    'use strict';

    var JMP = window.JellymountPlus;
    if (!JMP) return;
    if (!JMP.config.hoverPreview) return;

    var OPEN_DELAY = JMP.config.hoverPreviewDelayMs || 420;
    var EDGE_ZONE = 0.28;          // fraction of viewport treated as an edge
    var VIEWPORT_PAD = 12;         // px clamp padding
    var CARD_QUERY = '.itemsContainer .card[data-id], .card[data-id].itemAction, [is="emby-itemscontainer"] .card[data-id]';

    var openTimer = null;
    var currentCard = null;
    var previewEl = null;
    var currentItemId = null;
    var suppressUntil = 0;

    function cacheBust() { /* noop — kept for clarity */ }

    /* ---------------- Lifecycle ---------------- */

    function schedule(card) {
        cancelTimer();
        if (Date.now() < suppressUntil) return;
        currentCard = card;
        currentItemId = card.getAttribute('data-id');
        openTimer = setTimeout(function () {
            openTimer = null;
            if (currentCard === card && card.isConnected) open(card);
        }, OPEN_DELAY);
    }

    function cancelTimer() {
        clearTimeout(openTimer);
        openTimer = null;
    }

    function close(instant) {
        cancelTimer();
        currentCard = null;
        currentItemId = null;
        if (!previewEl) return;
        var el = previewEl;
        previewEl = null;
        if (instant || JMP.reducedMotion()) {
            el.remove();
        } else {
            el.classList.add('is-closing');
            el.classList.remove('is-open');
            setTimeout(function () { el.remove(); }, 220);
        }
    }

    /* ---------------- Open ---------------- */

    function open(card) {
        var id = card.getAttribute('data-id');
        if (!id) return;
        close(true);
        currentItemId = id;

        JMP.getItem(id).then(function (item) {
            /* Bail if the hover already moved on. */
            if (!currentItemId || currentItemId !== id || !card.isConnected) return;
            render(card, item);
        }).catch(function () { /* preview silently skipped */ });
    }

    function render(card, item) {
        var el = JMP.el('div', 'jmp-preview');
        el.setAttribute('role', 'dialog');
        el.setAttribute('aria-label', item.Name || '');

        /* artwork */
        var art = JMP.el('div', 'jmp-preview-art');
        var artUrl = JMP.thumbUrl(item, 780) || JMP.backdropUrl(item, 780);
        if (artUrl) {
            var img = document.createElement('img');
            img.src = artUrl;
            img.alt = '';
            art.appendChild(img);
        }
        var logoUrl = JMP.logoUrl(item, 500);
        if (logoUrl) {
            var logo = document.createElement('img');
            logo.className = 'jmp-preview-logo';
            logo.src = logoUrl;
            logo.alt = '';
            art.appendChild(logo);
        }
        el.appendChild(art);

        /* info */
        var info = JMP.el('div', 'jmp-preview-info');
        var titleText = item.Type === 'Episode' && item.SeriesName ? item.SeriesName : item.Name;
        if (!logoUrl && titleText) {
            info.appendChild(JMP.el('h3', 'jmp-preview-title', JMP.esc(titleText)));
        }

        var meta = JMP.el('div', 'jmp-preview-meta', JMP.metaChips(item));
        if (meta.innerHTML) info.appendChild(meta);

        if (item.Type === 'Episode') {
            var se = JMP.fmtSeasonEp(item);
            if (se) info.appendChild(JMP.el('div', 'jmp-preview-episodeline', JMP.esc(se)));
        }

        if (item.Overview) {
            info.appendChild(JMP.el('p', 'jmp-preview-overview', JMP.esc(item.Overview)));
        }

        /* actions — emby-itemscontainer gives native play/resume/link/menu */
        var actions = JMP.itemsContainer('jmp-preview-actions');
        var resumable = JMP.isResumeable(item);
        var play = document.createElement('button');
        play.type = 'button';
        play.className = 'jmp-btn jmp-btn-play itemAction';
        play.innerHTML = '<span class="material-icons jmp-btn-icon" aria-hidden="true">play_arrow</span><span>' +
            JMP.esc(resumable ? 'Resume' : 'Play') + '</span>';
        JMP.applyItemAttrs(play, item, resumable ? 'resume' : 'play');
        actions.appendChild(play);

        var fav = item.UserData && item.UserData.IsFavorite;
        var mylist = document.createElement('button');
        mylist.type = 'button';
        mylist.className = 'jmp-btn jmp-btn-icon-round jmp-mylist' + (fav ? ' is-saved' : '');
        mylist.title = 'My List';
        mylist.setAttribute('aria-label', 'My List');
        mylist.setAttribute('aria-pressed', fav ? 'true' : 'false');
        mylist.innerHTML = '<span class="material-icons" aria-hidden="true">' + (fav ? 'check' : 'add') + '</span>';
        mylist.addEventListener('click', function (e) {
            e.stopPropagation();
            e.preventDefault();
            var c = JMP.api();
            if (!c) return;
            var makeFav = !(item.UserData && item.UserData.IsFavorite);
            c.updateFavoriteStatus(item.Id, makeFav).then(function () {
                item.UserData = item.UserData || {};
                item.UserData.IsFavorite = makeFav;
                mylist.classList.toggle('is-saved', makeFav);
                mylist.setAttribute('aria-pressed', makeFav ? 'true' : 'false');
                mylist.querySelector('.material-icons').textContent = makeFav ? 'check' : 'add';
            }).catch(function () { /* noop */ });
        });
        actions.appendChild(mylist);

        var more = document.createElement('a');
        more.className = 'jmp-btn jmp-btn-ghost itemAction';
        more.setAttribute('href', '#/details?id=' + encodeURIComponent(item.Id) +
            (item.ServerId ? '&serverId=' + encodeURIComponent(item.ServerId) : ''));
        more.innerHTML = '<span class="material-icons jmp-btn-icon" aria-hidden="true">info_outline</span>';
        more.setAttribute('aria-label', 'More info');
        actions.appendChild(more);

        info.appendChild(actions);

        /* progress */
        var pct = JMP.progressPct(item);
        if (pct > 0) {
            var bar = JMP.el('div', 'jmp-preview-progress', '<div style="width:' + pct + '%"></div>');
            info.appendChild(bar);
            var remaining = item.RunTimeTicks ? Math.max(0, item.RunTimeTicks - (item.UserData.PlaybackPositionTicks || 0)) : 0;
            if (remaining) {
                info.appendChild(JMP.el('div', 'jmp-preview-progress-meta',
                    JMP.esc(JMP.fmtRuntime(remaining) + ' remaining')));
            }
        }

        el.appendChild(info);
        document.body.appendChild(el);
        previewEl = el;

        position(el, card);

        /* keep open while hovering the preview itself */
        el.addEventListener('pointerleave', function (e) {
            if (card.contains(e.relatedTarget)) return;
            close();
        });

        requestAnimationFrame(function () {
            if (previewEl === el) el.classList.add('is-open');
        });
    }

    /* ---------------- Collision-aware positioning ---------------- */

    function position(el, card) {
        var rect = card.getBoundingClientRect();
        var vw = window.innerWidth;
        var vh = window.innerHeight;

        /* Width may differ from CSS var if the item is tiny — measure real size. */
        var w = el.offsetWidth;
        var h = el.offsetHeight;

        var centerX = rect.left + rect.width / 2;
        var left;

        if (centerX < vw * EDGE_ZONE) {
            /* left-edge card — grow to the right, aligned to the card */
            left = rect.left - Math.min(6, rect.width * 0.05);
            el.style.setProperty('--jmp-preview-origin', 'left center');
        } else if (centerX > vw * (1 - EDGE_ZONE)) {
            /* right-edge card — grow to the left */
            left = rect.right - w + Math.min(6, rect.width * 0.05);
            el.style.setProperty('--jmp-preview-origin', 'right center');
        } else {
            left = centerX - w / 2;
            el.style.setProperty('--jmp-preview-origin', 'center center');
        }

        left = Math.max(VIEWPORT_PAD, Math.min(left, vw - w - VIEWPORT_PAD));

        /* Prefer vertical centering on the card; clamp inside viewport. */
        var top = rect.top + rect.height / 2 - h / 2;
        top = Math.max(VIEWPORT_PAD, Math.min(top, vh - h - VIEWPORT_PAD));

        el.style.left = left + 'px';
        el.style.top = top + 'px';
    }

    /* ---------------- Delegated hover tracking ---------------- */

    function findCard(el) {
        while (el && el !== document) {
            if (el.nodeType === 1 && el.matches && el.matches(CARD_QUERY)) return el;
            el = el.parentNode;
        }
        return null;
    }

    document.addEventListener('pointerover', function (e) {
        if (e.pointerType === 'touch') return;
        /* Ignore cards inside our own UI (hero selector / preview). */
        if (e.target.closest && e.target.closest('.jmp-preview, .jmp-hero')) return;

        var card = findCard(e.target);
        if (card) {
            if (card !== currentCard) schedule(card);
            return;
        }
        /* Left every card — if we're not over the preview, start closing. */
        if (!previewEl || !previewEl.contains(e.target)) {
            /* Allow movement card→preview without closing. */
            if (currentCard && e.relatedTarget && previewEl && previewEl.contains(e.relatedTarget)) return;
            close();
        }
    }, true);

    document.addEventListener('pointerleave', function (e) {
        if (e.pointerType === 'touch') return;
        if (e.target.closest && e.target.closest('.jmp-preview, .jmp-hero')) return;
        var card = findCard(e.target);
        if (card && card === currentCard) {
            if (previewEl && e.relatedTarget && previewEl.contains(e.relatedTarget)) return;
            close();
        }
    }, true);

    /* ---------------- Close triggers ---------------- */

    window.addEventListener('scroll', function () { close(true); }, true);

    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') {
            close();
            suppressUntil = Date.now() + 400;
        }
    }, true);

    /* Fresh hover after navigation */
    JMP.register('hoverPreview', {
        onView: function () {
            close(true);
            suppressUntil = Date.now() + 350;
        }
    });
})();
/* ===== extras/scripts/details.js ===== */
/* ============================================================
   JellymountPlus — Detail page enhancements
   Keeps the cinematic header honest: fills in the logo when the
   controller left it empty, patches a missing backdrop, and
   makes the favourite button read as "My List" state.
   ============================================================ */
(function () {
    'use strict';

    var JMP = window.JellymountPlus;
    if (!JMP) return;

    function currentItemId() {
        var m = (location.hash || '').match(/[?&]id=([0-9a-fA-F]+)/);
        return m ? m[1] : null;
    }

    function enhance(view) {
        var id = currentItemId();
        if (!id) return;

        var backdrop = view.querySelector('.itemBackdrop');
        var logo = view.querySelector('.detailLogo');
        if (!backdrop && !logo) {
            /* Detail DOM isn't rendered yet — wait for it. */
            JMP.watch(view, function () {
                return view.querySelector('.itemBackdrop') || view.querySelector('.detailLogo');
            }, function () { enhance(view); });
            return;
        }

        JMP.getItem(id).then(function (item) {
            if (!view.isConnected) return;

            /* Backdrop: only fill when Jellyfin left it blank. */
            if (backdrop && !backdrop.style.backgroundImage && !backdrop.querySelector('img')) {
                var url = JMP.backdropUrl(item, 1920);
                if (url) backdrop.style.backgroundImage = 'url("' + url + '")';
            }

            /* Logo: only fill when controller produced nothing. */
            if (logo && !logo.style.backgroundImage && !logo.querySelector('img')) {
                var lurl = JMP.logoUrl(item, 800);
                if (lurl) logo.style.backgroundImage = 'url("' + lurl + '")';
            }
        }).catch(function () { /* leave default look */ });
    }

    JMP.register('details', {
        onView: function (view) {
            if (!view) return;
            var isDetail = view.classList && (view.classList.contains('itemDetailPage') || view.id === 'itemDetailPage');
            if (!isDetail) return;
            /* Content populates async — give it a beat, then patch gaps. */
            setTimeout(function () { if (view.isConnected) enhance(view); }, 400);
        }
    });
})();
